// SLIP-39 against the reference implementation: share sets split by
// python-shamir-mnemonic v0.3.0 (the SLIP-0039 reference implementation,
// MIT) with a recorded random source (test/fixtures/slip39/reference-sets.json,
// regenerated by scripts/slip39-reference.py).
//
// Contract compared: src/js/slip39.js combines every threshold subset to the
// reference's master secret and encrypted master secret, reads the
// identifier and flags the reference wrote, and rebuilds exactly the random
// values the reference drew for the groups the subset uses: R of each digest
// share and the shares drawn at random at x = 0..T-3, at both levels. A set
// with one share or one group more than its threshold is refused. The
// randomness test finds each planted repeat or pattern and nothing in
// independent sets. Expected values are the reference's recorded draws and
// the fixture's plan, never this repository's output.
// Run with: npm test
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { MiniDocument } from "./mini-dom.mjs";
import { combineSlip39, parseSlip39Share, recoverSlip39, slip39RandomValues, testSlip39Randomness } from "../src/js/slip39.js";
import { mountSlip39Check } from "../src/js/slip39-check.js";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const fixture = JSON.parse(readFileSync(join(root, "test/fixtures/slip39/reference-sets.json"), "utf8"));
const set = (name) => fixture.sets.find((entry) => entry.name === name);
const hex = (bytes) => Buffer.from(bytes).toString("hex");
const ascii = (text) => new TextEncoder().encode(text);
const parse = (mnemonics) => mnemonics.map((mnemonic) => {
  const parsed = parseSlip39Share(mnemonic);
  assert.equal(parsed.ok, true, parsed.reason);
  return parsed.share;
});

// Threshold subsets: the first groups' first members, and the last groups'
// last members (whose random shares at low x must be interpolated, not read).
const subsets = (entry) => {
  const take = (groups, members) => groups.flatMap((group) => members(entry.mnemonics[group], entry.groups[group][0]));
  const indices = entry.groups.map((_, i) => i);
  return [
    { groups: indices.slice(0, entry.groupThreshold), mnemonics: take(indices.slice(0, entry.groupThreshold), (list, t) => list.slice(0, t)) },
    { groups: indices.slice(-entry.groupThreshold), mnemonics: take(indices.slice(-entry.groupThreshold), (list, t) => list.slice(-t)) },
  ];
};
const key = ({ level, group, x }) => `${level}:${level === "group" ? "-" : group}:${x}`;
// The reference's draws for the groups a subset uses, keyed as rebuilt values are.
const drawnFor = (entry, groups) => new Map(entry.draws
  .filter((draw) => draw.kind !== "identifier" && (draw.level === "group" || groups.includes(draw.group)))
  .map((draw) => [key({ level: draw.level, group: draw.group ?? null, x: draw.x }), draw.hex]));

test("the fixture is the reference's, from the pinned generator", () => {
  assert.equal(fixture.source.version, "0.3.0");
  assert.equal(fixture.source.commit, "08bbb74bdcb58c918981836cb3ccf401e57ecfb4");
  assert.equal(fixture.source.generator, "scripts/slip39-reference.py");
  assert.equal(fixture.sets.length, 19);
});

for (const entry of fixture.sets) {
  test(`reference set "${entry.name}": every subset combines and rebuilds the drawn random values`, () => {
    for (const subset of subsets(entry)) {
      const shares = parse(subset.mnemonics);
      for (const share of shares) {
        assert.equal(share.identifier, entry.identifier);
        assert.equal(share.extendable, entry.extendable);
        assert.equal(share.iterationExponent, entry.iterationExponent);
        assert.equal(share.groupThreshold, entry.groupThreshold);
        assert.equal(share.groupCount, entry.groups.length);
        assert.equal(share.memberThreshold, entry.groups[share.groupIndex][0]);
      }
      const recovered = recoverSlip39(shares);
      assert.equal(recovered.ok, true, recovered.reason);
      assert.equal(hex(recovered.ems), entry.encryptedMasterSecret);
      const random = slip39RandomValues(shares);
      assert.equal(random.ok, true);
      const rebuilt = new Map(random.values.map((value) => [key(value), hex(value.bytes)]));
      assert.deepEqual([...rebuilt.entries()].sort(), [...drawnFor(entry, subset.groups).entries()].sort(), `groups ${subset.groups}`);
    }
    // Decryption is the slow part: once per set.
    const combined = combineSlip39(parse(subsets(entry)[1].mnemonics), ascii(entry.passphrase));
    assert.equal(combined.ok, true, combined.reason);
    assert.equal(hex(combined.masterSecret), entry.masterSecret);
  });
}

test("one share or one group over the threshold is refused; exactly the threshold is accepted", () => {
  // Groups (2 of 3), (3 of 5), (1 of 1); 2 groups needed.
  const entry = set("2 of 3 groups, 128-bit, not extendable");
  const [first, second, third] = entry.mnemonics;
  assert.equal(recoverSlip39(parse([...first.slice(0, 2), ...second.slice(0, 3)])).ok, true);
  assert.deepEqual(recoverSlip39(parse([...first.slice(0, 3), ...second.slice(0, 3)])), { ok: false, reason: "too-many-members", group: 0, have: 3, need: 2 });
  assert.deepEqual(recoverSlip39(parse([...first.slice(0, 2), ...second.slice(0, 3), ...third])), { ok: false, reason: "too-many-groups", have: 3, need: 2 });
  assert.deepEqual(recoverSlip39(parse([...first.slice(0, 2), ...second.slice(0, 2)])), { ok: false, reason: "too-few-members", group: 1, have: 2, need: 3 });
});

// The randomness test on the reference's sets, each built to show one thing.
const threshold = (name) => parse(subsets(set(name))[0].mnemonics);
const compare = (a, b) => {
  const outcome = testSlip39Randomness(threshold(a), threshold(b));
  assert.equal(outcome.ok, true, outcome.reason);
  return outcome.findings;
};
const describe = (finding) => {
  const place = (value) => `${value.level}:${value.level === "group" ? "-" : value.group}:${value.x}`;
  if (finding.kind === "repeat" || finding.kind === "repeat-within") return `${finding.kind}${finding.set ? ` ${finding.set}` : ""} ${place(finding.a)}~${place(finding.b)} ${finding.length}${finding.whole ? " whole" : ""}`;
  if (finding.kind === "pattern") return `pattern ${finding.set} ${place(finding.value)} ${finding.pattern}`;
  return finding.kind;
};
const findingsOf = (a, b) => compare(a, b).map(describe).sort();

test("independent runs share nothing, at one level and at two", () => {
  assert.deepEqual(findingsOf("run 1", "run 2"), []);
  assert.deepEqual(findingsOf("groups run 1", "groups run 2"), []);
});

test("a generator restarted from the same state repeats every draw, shifted or not", () => {
  // Same identifier, same random share at x = 0 and same R.
  assert.deepEqual(findingsOf("run 1", "run 1 restarted"), ["repeat member:0:0~member:0:0 16 whole", "repeat member:0:254~member:0:254 12 whole", "same-identifier"]);
  // A 2-of-3 split reads the stream differently: its R is the start of run 1's random share.
  assert.deepEqual(findingsOf("run 1", "run 1 restarted, 2-of-3"), ["repeat member:0:0~member:0:254 12", "same-identifier"]);
  // Only the group-level R repeats.
  assert.deepEqual(findingsOf("groups run 1", "groups run 3, reusing run 1's group-level R"), ["repeat group:-:254~group:-:254 12 whole"]);
});

test("a generator that returns the same buffer, or trivial values, is caught within one set", () => {
  assert.deepEqual(findingsOf("one buffer every call", "run 2"), ["repeat-within a member:0:254~member:0:0 12"]);
  assert.deepEqual(findingsOf("zero digest random", "run 2"), ["pattern a member:0:254 zero"]);
  assert.deepEqual(findingsOf("repeated byte share", "run 2"), ["pattern a member:0:0 repeated-byte"]);
  assert.deepEqual(findingsOf("counter digest random", "run 2"), ["pattern a member:0:254 counter"]);
});

test("the panel reports a restarted generator end to end", () => {
  const doc = new MiniDocument();
  const host = doc.createElement("div");
  doc.body.appendChild(host);
  mountSlip39Check(host, { doc });
  doc.getElementById("slip39-check-mode").querySelector('[data-value="randomness"]').click();
  for (const [name, entry] of [["a", "run 1"], ["b", "run 1 restarted"]]) {
    const mnemonics = subsets(set(entry))[1].mnemonics;
    while (doc.querySelectorAll(`textarea[data-slip39-set="${name}"]`).length < mnemonics.length) doc.getElementById(`slip39-check-add-${name}`).click();
    for (const [i, field] of doc.querySelectorAll(`textarea[data-slip39-set="${name}"]`).entries()) field.value = mnemonics[i];
  }
  doc.getElementById("slip39-check-compare").click();
  assert.equal(doc.getElementById("slip39-check-result").getAttribute("data-state"), "repeats");
  assert.deepEqual(doc.getElementById("slip39-check-findings").querySelectorAll("li").map((item) => item.getAttribute("data-slip39-finding")).sort(), ["repeat", "repeat", "same-identifier"]);
});
